from pathlib import Path
import json,math
p=Path('CAD/Design_Completion');old=json.loads((p/'INERTIA_LOAD_SCREEN.json').read_text())
f=old['peak_abs_rod_force_N'];torque=old['peak_abs_blade_hinge_torque_Nm'];E_required=(3*f)*46.52665325007647**2/(math.pi**2*(math.pi/64*(2**4-1**4)))
web_I=2*(1.7*5.4**3/12);web_Z=web_I/(5.4/2);bend=f*22.075
bond_area=math.pi*2*2.5
result={'status':'PROVISIONAL MECHANISM SCREEN; NOT FATIGUE OR STRUCTURAL CERTIFICATION','source_load':'INERTIA_LOAD_SCREEN.json; baseline12.5g blade and uniform chord mass assumption,2640RPM, no aero/friction/jam loads','rod_force_scale_N':f,'hinge_torque_scale_Nm':torque,'web_assumption':'Two uninterrupted rectangular1.7x5.4mm webs. This excludes boss fillets, holes, recesses, local load entry and shear/torsional interaction; not a verified minimum-section/FEA result.','arm_offset_mm':22.075,'idealized_web_second_moment_mm4':web_I,'idealized_web_section_modulus_mm3':web_Z,'offset_bending_moment_Nmm':bend,'idealized_web_bending_stress_MPa':bend/web_Z,'D3_UNDRILLED_round_journal_torsional_stress_MPa':16*torque*1000/(math.pi*3**3),'crosspin_equivalent_torque_force_at_radius1p5_N':torque/.0015,'pin_supplier_double_shear_rating_N':600.,'pin_rating_source':'https://www.spirol.com/assets/files/cldp-coiled-spring-pins-design-guide-us.pdf printed17 ISO8750D1; supplier ultimate-type test value, not allowable fatigue stress','pin_limits':'No reserve factor claimed: actual load sharing with D-flat, bending, press fit/host damage, axial pullout and cyclic duty are unverified. Installed solid reference is not actual coiled-section mass/geometry.','tube_OD_ID_length_mm':[2,1,46.52665325007647],'tube_E_required_GPa_for_3x_screen':E_required/1000,'tube_E_assumption':'No actual modulus assigned. Euler pinned-pinned full tube length; required modulus for3x inertial-force screen only; end bonds, compression damage and imperfections require qualification. Three is a proposed screening multiplier, not approved design factor.','bond_cylindrical_area_each_mm2':bond_area,'bond_mean_shear_at_inertia_force_MPa':f/bond_area,'bond_mean_shear_at_3x_screen_MPa':3*f/bond_area,'bond_limits':'No adhesive selected/qualified. Average shear ignores peel, end effects, preparation, gap, cure, fatigue and temperature. Tube insertion2.5mm preserved.','release_holds':['Approve operating/aerodynamic/imbalance/stop load cases and required cycles','Define metal trunnion and its bond into specified blade spar/core; monolithic Part1 is only a geometry proxy','Assess drilled D3 trunnion fatigue and actual D-flat/hole geometry; undrilled torsion formula is not applicable as acceptance criterion','Verify actual twin-web minimum sections, boss/fillet stress and combined loading','Qualify pin press retention, adhesive pullout/cyclic fatigue, joint wear and anti-loosening','Guarded physical proof, balance/vibration and staged speed validation']}
assert result['tube_E_required_GPa_for_3x_screen']>0 and result['idealized_web_bending_stress_MPa']>0
(p/'ARM_ROD_RETENTION_STRENGTH_SCREEN.json').write_text(json.dumps(result,indent=2));print('PROVISIONAL_ARM_ROD_SCREEN',round(result['idealized_web_bending_stress_MPa'],2), 'MPa; required tube modulus', round(E_required/1000,2),'GPa')
